class Solution:
    def repeatedCharacter(self, s: str) -> str:
        seen = set()
        for c in s:
            if c in seen:
                return c
            seen.add(c)
        return ''

c.cpp:
class Solution {
public:
    char repeatedCharacter(string s) {
        bool seen[26] = {false};
        for (char c : s) {
            if (seen[c - 'a']) return c;
            seen[c - 'a'] = true;
        }
        return ' ';
    }
};

