    char repeatedCharacter(string s) {
        int mask = 0;
        for (char c : s) {
            int bit = 1 << (c - 'a');
            if (mask & bit) return c;
            mask |= bit;
        }
        return ' ';
    }
};

c.java:
class Solution {
    public char repeatedCharacter(String s) {
        int mask = 0;
        for (char c : s.toCharArray()) {
            int bit = 1 << (c - 'a');
            if ((mask & bit) != 0) return c;
            mask |= bit;
        }
        return ' ';
    }
}

